import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (date: Date) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (date: Date, days: number) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);

const isSameDay = (a: Date | null, b: Date) =>
  a != null &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
}: ReportDatePickerProps) {
  const isControlled = value !== undefined;
  const [internalDate, setInternalDate] = useState<Date | null>(
    defaultValue ? startOfDay(defaultValue) : null,
  );
  const selected = isControlled ? (value ? startOfDay(value) : null) : internalDate;
  const [month, setMonth] = useState<Date>(selected ?? startOfDay(new Date()));

  const today = startOfDay(new Date());
  const presets: { id: string; label: string; date: Date }[] = [
    { id: 'today', label: 'Сегодня', date: today },
    { id: 'yesterday', label: 'Вчера', date: shiftDays(today, -1) },
    { id: 'week-ago', label: 'Неделя назад', date: shiftDays(today, -7) },
  ];

  const select = (next: Date | null) => {
    if (!next) return;
    const normalized = startOfDay(next);
    if (!isControlled) setInternalDate(normalized);
    setMonth(normalized);
    onChange?.(normalized);
  };

  return (
    <div
      className="jx-stack"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {presets.map((preset) => (
          <JxButton
            key={preset.id}
            type="button"
            size="sm"
            variant={isSameDay(selected, preset.date) ? 'primary' : 'secondary'}
            aria-pressed={isSameDay(selected, preset.date)}
            onClick={() => select(preset.date)}
          >
            {preset.label}
          </JxButton>
        ))}
      </div>

      <JxCalendar
        aria-label="Дата отчёта"
        value={selected}
        onValueChange={select}
        month={month}
        onMonthChange={setMonth}
        max={today}
      />

      <p style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}>
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString('ru-RU')}`
          : 'Дата отчёта не выбрана'}
      </p>
    </div>
  );
}

